  @protected
  CoreError dco_decode_core_error(dynamic raw) {
    // Codec=Dco (DartCObject based), see doc to use other codecs
    switch (raw[0]) {
      case 0:
        return CoreError_NotFound(
          entity: dco_decode_String(raw[1]),
          id: dco_decode_String(raw[2]),
        );
      case 1:
        return CoreError_InvalidInput(
          field: dco_decode_String(raw[1]),
          reason: dco_decode_String(raw[2]),
        );
      case 2:
        return CoreError_StaleCard(cardId: dco_decode_String(raw[1]));
      case 3:
        return CoreError_NoActivePlan();
      case 4:
        return CoreError_ContentCorrupt(
          file: dco_decode_String(raw[1]),
          detail: dco_decode_String(raw[2]),
        );
      case 5:
        return CoreError_MigrationFailed(
          fromVersion: dco_decode_i_32(raw[1]),
          message: dco_decode_String(raw[2]),
        );
      case 6:
        return CoreError_Storage(message: dco_decode_String(raw[1]));
      case 7:
        return CoreError_Internal(message: dco_decode_String(raw[1]));
      default:
        throw Exception("unreachable");
    }
  }

