  @protected
  void sse_encode_core_error(CoreError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case CoreError_NotFound(entity: final entity, id: final id):
        sse_encode_i_32(0, serializer);
        sse_encode_String(entity, serializer);
        sse_encode_String(id, serializer);
      case CoreError_InvalidInput(field: final field, reason: final reason):
        sse_encode_i_32(1, serializer);
        sse_encode_String(field, serializer);
        sse_encode_String(reason, serializer);
      case CoreError_StaleCard(cardId: final cardId):
        sse_encode_i_32(2, serializer);
        sse_encode_String(cardId, serializer);
      case CoreError_NoActivePlan():
        sse_encode_i_32(3, serializer);
      case CoreError_ContentCorrupt(file: final file, detail: final detail):
        sse_encode_i_32(4, serializer);
        sse_encode_String(file, serializer);
        sse_encode_String(detail, serializer);
      case CoreError_MigrationFailed(
        fromVersion: final fromVersion,
        message: final message,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_i_32(fromVersion, serializer);
        sse_encode_String(message, serializer);
      case CoreError_Storage(message: final message):
        sse_encode_i_32(6, serializer);
        sse_encode_String(message, serializer);
      case CoreError_Internal(message: final message):
        sse_encode_i_32(7, serializer);
        sse_encode_String(message, serializer);
    }
  }

